import { keyBy, mapValues, uniq } from 'es-toolkit';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function doubled(scores: Record<string, number>): Record<string, number> {
  return mapValues(scores, (score) => score * 2);
}

export function byNameKey(rows: Row[]): Record<string, Row> {
  return keyBy(rows, (row) => row.name);
}

// Input is sorted, so first-occurrence dedupe (uniq) matches sortedUniq exactly.
export function dedupeSorted(values: number[]): number[] {
  return uniq(values);
}
```

Choices I made:
- **`doubled`** → es-toolkit `mapValues` directly. Same key iteration (own enumerable keys) as lodash.
- **`byNameKey`** → es-toolkit `keyBy` with a one-line arrow in place of lodash's property shorthand. This is the adapter for the differing call shape. Later rows win on duplicate names, as before. I confirmed this with the example input.
- **`dedupeSorted`** → es-toolkit has no `sortedUniq`, so I used `uniq`. For sorted input it keeps first occurrences in order, which gives the same output as `sortedUniq`. I did not hand-write a replacement.
- The `Row` and `Config` exports and all three signatures are unchanged.

